package com.cybershield.controller; import com.cybershield.model.*; import com.cybershield.repository.*; import org.springframework.security.core.Authentication; import org.springframework.security.access.AccessDeniedException; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController { final NotificationRepository r;final UserRepository u;public NotificationController(NotificationRepository r,UserRepository u){this.r=r;this.u=u;} @GetMapping List<Notification> all(Authentication a){return r.findTop30ByUserIdOrderByCreatedAtDesc(u.findByEmail(a.getName()).orElseThrow().getId());} @GetMapping("/count") long count(Authentication a){return r.countByUserIdAndReadFlagFalse(u.findByEmail(a.getName()).orElseThrow().getId());} @PatchMapping("/{id}/read") Notification read(@PathVariable Long id,Authentication a){Notification n=r.findById(id).orElseThrow();if(!n.getUser().getEmail().equals(a.getName()))throw new AccessDeniedException("Notification access denied");n.setReadFlag(true);return r.save(n);} }
